   EX('Power Rule for Integrals', 'Add 1 to the exponent, divide by the new exponent. +C!', r'⟨\int (6x^2 - 4x + 3)\,dx⟩', [['Integrate:', r'⟨2x^3 - 2x^2 + 3x⟩']], r'⟨2x^3 - 2x^2 + 3x + C⟩', D('2*x**3-2*x**2+3*x', '6*x**2-4*x+3')),
