   TB('Cross-Section Areas', ['Shape (side s)', 'Area'], [['Square', r'⟨s^2⟩'], ['Equilateral triangle', r'⟨\tfrac{\sqrt{3}}{4}s^2⟩'], ['Semicircle (diameter s)', r'⟨\tfrac{\pi}{8}s^2⟩']], 'Squares on y = √x, 0 ≤ x ≤ 4: V = ∫ x dx = 8.', N('16/2', 8)),
