sheet('calculus-differential-equations', C, 8, 'Differential Equations',
  'slope fields and verifying solutions', 'separation of variables and exponential growth and decay',
  [V('Key Vocabulary', [['differential equation', 'Relates a function and its derivatives.', r'⟨\tfrac{dy}{dx} = 2y⟩'], ['general solution', 'Contains + C.', r'⟨y = Ce^{2x}⟩'], ['particular solution', 'C found from an initial condition.', r'⟨y = 3e^{2x}⟩'], ['slope field', 'Small slope segments at grid points.', 'shows solution curves']]),
   EX('Verifying a Solution', 'Differentiate and substitute.', r'Is ⟨y = e^{3x}⟩ a solution of y′ = 3y?', [['y′:', r'⟨3e^{3x} = 3y⟩ ✓']], 'Yes', N('3*Math.exp(0.6)-3*Math.exp(0.6)', 0)),
   EX('Slope at a Point', 'Plug the point into dy/dx.', r'⟨\tfrac{dy}{dx} = x - y⟩ at (3, 1)', [['Compute:', '3 − 1']], 'slope 2', N('3-1', 2)),
   W('Reading Slope Fields', [['Slopes depend only on x', 'same along vertical columns'], ['Slopes depend only on y', 'same along horizontal rows'], ['dy/dx = 0', 'horizontal segments (equilibrium if y = c)']]),
   EX('Euler’s Method', r'⟨y_{new} = y + \tfrac{dy}{dx}\Delta x⟩', r'⟨\tfrac{dy}{dx} = x + y⟩, y(0) = 1, Δx = 0.1. Estimate y(0.1).', [['Step:', '1 + (0 + 1)(0.1)']], '1.1', N('1+1*0.1', 1.1)),
   MS('Quick Reminders & Common Mistakes', ['Slope fields show slope, not y-values.', 'Particular solution: solve for C.', 'Check the solution by differentiating.'],
      [['Forgetting + C', 'add C right after integrating'], ['Plugging the point in before integrating', 'integrate first'], ['Confusing x and y in the slope', 'use (x, y) in order']])],
  [L('Separation of Variables', ['1. Get all y’s with dy, all x’s with dx.', '2. Integrate both sides (+ C on one side).', '3. Use the initial condition to find C.', '4. Solve for y if possible.']),
   EX('Separating Variables', 'Divide by y, multiply by dx.', r'⟨\tfrac{dy}{dx} = xy⟩, y(0) = 2', [['Separate:', r'⟨\int \tfrac{dy}{y} = \int x\,dx⟩'], ['Integrate:', r'⟨\ln|y| = \tfrac{x^2}{2} + C⟩']], r'⟨y = 2e^{x^2/2}⟩', N('2*Math.exp(0)', 2)),
   EX('Another Separable Equation', 'Separate, integrate, solve.', r'⟨\tfrac{dy}{dx} = \tfrac{x}{y}⟩, y(0) = 3', [['Integrate:', r'⟨\tfrac{y^2}{2} = \tfrac{x^2}{2} + C⟩'], ['C:', r'⟨\tfrac{9}{2}⟩']], r'⟨y = \sqrt{x^2 + 9}⟩', N('Math.sqrt(0+9)', 3)),
   TB('Exponential Growth and Decay', ['Model', 'Solution'], [[r'⟨\tfrac{dy}{dt} = ky⟩', r'⟨y = y_0e^{kt}⟩'], ['k > 0', 'growth'], ['k < 0', 'decay']]),
   EX('Half-Life', r'Use the half-life to find k: ⟨\tfrac{1}{2} = e^{kT}⟩.', 'Half-life 10 years; 80 g at t = 0. Amount at t = 30?', [['Three half-lives:', r'⟨80(\tfrac{1}{2})^3⟩']], '10 g', N('80*0.5**3', 10)),
   L('Check Yourself', ['Did I separate before integrating?', 'Did I add + C and solve for it?', 'Is my k positive for growth, negative for decay?', 'Does my solution pass through the initial point?'])])

